import { utf8Encode } from './bytes.ts';
import {
  mergePackParts,
  parsePackPayload,
  parsePackPart,
  type PackManifest,
  type PackPayload,
} from './pack-schema.ts';
import type { ContentPack, PackChunk } from './content-source.ts';

// Every build ships a full pack so first launch works offline (FE02 behaviour
// 1, AC-02.1). The values are regenerated by the content pipeline; tests cover
// the signature and hash checks on this exact data.
export const BUNDLED_PACK_VERSION = '2026.11.1';
export const BUNDLED_DATA_FORMAT = '1';

const CHUNK_ONE_JSON =
  '{"items":[{"id":"country.fra","names":{"en-GB":"France","en-US":"France"}},{"id":"country.deu","names":{"en-GB":"Germany","en-US":"Germany"}}]}';
const CHUNK_TWO_JSON =
  '{"flags":[{"id":"dailyChallenge","default":false}],"experiments":[],"tuning":{"dailyGoal":10},"daily":{"schedule":[{"date":"2026-11-19"}]}}';

const CHUNK_ONE_SHA256 = '6290addf61b625d3800cb8e5b26a60db0fbe2ed9adb9b47323f8d0d2a6eee1e0';
const CHUNK_TWO_SHA256 = '7f6cf362dcb37b122b3b75b55b490847d32409df750b390eb7819c7143c83259';

const BUNDLED_MANIFEST: PackManifest = {
  formatVersion: 1,
  packVersion: '2026.11.1',
  dataFormat: '1',
  createdAt: 1763500800000,
  chunks: [
    {
      sha256: '6290addf61b625d3800cb8e5b26a60db0fbe2ed9adb9b47323f8d0d2a6eee1e0',
    },
    {
      sha256: '7f6cf362dcb37b122b3b75b55b490847d32409df750b390eb7819c7143c83259',
    },
  ],
  signature: {
    keyId: 'pack-key-bundled-2026-01',
    value:
      'Ejv5LZSkYG8FsQbDxGvQhmvWor39ed424loHfX2ZlSIErEOGkGHex5aUdhQaiaJEeD/p03dN2kdeljUlLcffAw==',
  },
};

function chunks(): readonly PackChunk[] {
  return [
    { sha256: CHUNK_ONE_SHA256, data: utf8Encode(CHUNK_ONE_JSON) },
    { sha256: CHUNK_TWO_SHA256, data: utf8Encode(CHUNK_TWO_JSON) },
  ];
}

export function createBundledContentPack(): ContentPack {
  const parts = [
    parsePackPart(JSON.parse(CHUNK_ONE_JSON)),
    parsePackPart(JSON.parse(CHUNK_TWO_JSON)),
  ];
  const merged = mergePackParts(parts);
  const payload: PackPayload = parsePackPayload(merged);
  return {
    packVersion: BUNDLED_PACK_VERSION,
    dataFormat: BUNDLED_DATA_FORMAT,
    manifest: BUNDLED_MANIFEST,
    payload,
    chunks: chunks(),
  };
}

export const BUNDLED_CONTENT_PACK: ContentPack = createBundledContentPack();
